<?php get_header(); ?><main><?php while(have_posts()): the_post(); ?><article <?php post_class('cvng-article'); ?>><header class="cvng-article-head"><div class="cvng-wrap cvng-reading"><div class="cvng-post-meta"><?php echo esc_html(get_the_date('j F Y')); ?><?php $cats=get_the_category(); if($cats){ echo ' · '.esc_html($cats[0]->name); } ?></div><h1 class="cvng-article-title"><?php the_title(); ?></h1><?php if(has_excerpt()): ?><p class="cvng-article-deck"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?></div></header><?php if(has_post_thumbnail()): ?><div class="cvng-wrap cvng-reading cvng-featured"><?php the_post_thumbnail('full'); ?></div><?php endif; ?><div class="cvng-wrap cvng-reading cvng-prose"><?php the_content(); ?></div><footer class="cvng-wrap cvng-reading cvng-article-footer"><div class="cvng-quote">Le SI est un outil. Pas une finalité.</div></footer></article><?php endwhile; ?></main><?php get_footer(); ?>